mapper.select:
select ag.Ag_Name as agName, pp.PP_Name as ppName, dp.PD_Name as pdName, u.U_MTel as uMtel, u.U_Tel as uTel, c1.C_Name as Cname, c1.C_Name as cAbbName, mn.* from OA_Attendance_Member mn left join OA_Attendance_Group ag on ag.Ag_Id=mn.Ag_Id left join SYS_Position_P pp on pp.Pp_Id=mn.Pp_Id left join SYS_Department_P dp on pp.Pd_Id=dp.Pd_Id left join SYS_User u on u.U_ID=mn.Am_Uid left join SYS_Company c1 on u.C_ID=c1.C_ID where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by ag.Ag_Create_Time desc
limit #{params.start},#{params.size}
